import os,re
root='AlgebraicJacobian'
mods={}
for d,_,fs in os.walk(root):
    for f in fs:
        if f.endswith('.lean'):
            p=os.path.join(d,f); name=p[:-5].replace('/','.')
            txt=open(p).read()
            mods[name]=(re.findall(r'^import\s+(AlgebraicJacobian\S*)',txt,re.M),txt)
def cone(n,seen=None):
    if seen is None: seen=set()
    if n in seen or n not in mods: return seen
    seen.add(n)
    for i in mods[n][0]: cone(i,seen)
    return seen
pat=re.compile(r'(?<![\w.])sorry(?![\w])')
def strip(t):
    t=re.sub(r'/-.*?-/','',t,flags=re.S); return re.sub(r'--[^\n]*','',t)
for tgt in ['AlgebraicJacobian.Picard.DualNumberChartTriviality','AlgebraicJacobian.RiemannRoch.WeilDivisor','AlgebraicJacobian.Picard.IdentityComponent']:
    c=cone(tgt)
    bad={m:len(pat.findall(strip(mods[m][1]))) for m in c if pat.search(strip(mods[m][1]))}
    print(tgt,"cone",len(c),"modules with sorry-terms:",bad)
EOF
